/**
 * OrbitControls 的阻尼是**按帧**衰减的，不是按时间。
 *
 * three r0.185 的 `OrbitControls.update(deltaTime = null)` 只用 `deltaTime` 算自动旋转角度
 * （`_getAutoRotationAngle`），而惯性衰减写死在每帧一次：
 *
 * ```js
 * _spherical.theta += _sphericalDelta.theta * this.dampingFactor;   // 累加
 * _sphericalDelta.theta *= (1 - this.dampingFactor);                // 衰减
 * ```
 *
 * 于是 60fps 下调好的 `dampingFactor = 0.09`（约 0.5 秒收敛）在手机上 8fps 时要等
 * `ln(0.01)/ln(0.91) ≈ 49` 帧 ≈ **6 秒**才停下来：手指抬起后模型还在慢慢飘，
 * 拖拽时的位移也被"摊"在多帧里，手感就是"一次只移动一点点 / 跟不上手"。
 *
 * 这里把基准系数（60fps 下的每帧衰减）换算成当前帧时长下等价的每帧衰减：
 * 让**墙钟时间**上的收敛速度与帧率无关。`1 / 240` 的下限是防止帧时长极小
 * （高刷屏 + 极快帧）时系数被算成 0，`0.9` 的上限是防止一帧跳完导致突进。
 */
export const dampingForFrame = (base: number, frameSeconds: number): number => {
  const seconds = Math.max(frameSeconds, 1 / 240);
  return Math.min(0.9, 1 - Math.pow(1 - base, seconds * 60));
};
